\label{th:noise-stability-informal}
	Given parameters $k \ge 2$, $\rho \in [0,1]$ and $\varepsilon > 0$, there exists an explicitly computable $n_0 = n_0(\rho, k, \varepsilon)$ such that the following holds:

	\noindent For any $n \in {\mathbb N}$, let $f : {\mathbb R}^n \to \Delta_k$. Then, there exists a function $\wtilde{f} : {\mathbb R}^{n_0} \to \Delta_k$ such that
	\begin{enumerate}
		\item $\norm{1}{\mathbb{E}[f] - \mathbb{E}[\wtilde{f}]} \le \varepsilon$.
		\item $\mathsf{Stab}_\rho(\wtilde{f}) \ge \mathsf{Stab}_\rho(f) - \varepsilon$.
	\end{enumerate}
	Moreover, there exists an explicitly computable $d_0 = d_0(\rho, k, \varepsilon)$ for which there is a degree-$d_0$ polynomial $g : {\mathbb R}^{n_0} \to {\mathbb R}^k$, such that, $\wtilde{f}({\bm a}) = \mathcal{R}\inparen{g\inparen{\frac{{\bm a}}{\|{\bm a}\|_2}}}$.\\

	\noindent The explicit $n_0$ and $d_0$ are upper bounded as $n_0 \le \exp \inparen{\mathrm{poly}\inparen{k, \frac{1}{1-\rho}, \frac{1}{\varepsilon}}}$ and $d_0 \le \mathrm{poly}\inparen{k, \frac{1}{1-\rho}, \frac{1}{\varepsilon}}$.

\begin{equation}\label{eqn:dim-red-substitution}
\wtilde{A}({\bm a}) := A\inparen{\frac{M {\bm a}}{\norm{2}{{\bm a}}}} \qquad \ \mathrm{and} \ \qquad \wtilde{B}({\bm b}) := B\inparen{\frac{M {\bm b}}{\norm{2}{{\bm b}}}}
\end{equation}

\label{th:dim_red_Gauss_space}
	Given parameters $k \ge 2$, $d \in \mathcal{Z}_{\ge 0}$, $\rho \in (0,1)$ and $\delta > 0$, there exists an \emph{explicitly computable} $D = D(d, k, \delta)$, such that the following holds:

	Let $A: {\mathbb R}^N \to {\mathbb R}^k$ and $B: {\mathbb R}^N \to {\mathbb R}^k$ be degree-$d$ multilinear polynomials. Additionally, suppose that $\mathrm{dist}(A, \Delta_k), \mathrm{dist}(B, \Delta_k) \le \delta$. Consider the functions $\wtilde{A} : {\mathbb R}^D \to {\mathbb R}^k$ and $\wtilde{B} : {\mathbb R}^D \to {\mathbb R}^k$ as defined in \Cref{eqn:dim-red-substitution}. With {\em probability} at least $1-3\delta$ over the random choice of $M \sim \mathcal{N}(0,1)^{N \times D}$, the following will hold:
	\begin{itemize}
		\item For every $i, j \in [k]$ : $\inabs{\inangle{A_i, B_j}_{\mathcal{G}_\rho^{\otimes N}} ~-~ \inangle{\wtilde{A}_i, \wtilde{B}_j}_{\mathcal{G}_\rho^{\otimes D}}} ~\le~ \delta$.
		\item $\mathrm{dist}(\wtilde{A}, \Delta_k) \le \sqrt{\delta}$ and $\mathrm{dist}(\wtilde{B}, \Delta_k) \le \sqrt{\delta}$.
	\end{itemize}

	In particular, $D$ is an explicit function upper bounded by $\exp\inparen{\mathrm{poly}\inparen{d, \log k, \log(\frac{1}{\delta})}}$.

 \label{def:max_corr}
	Given a joint probability space $(\mathcal{Z} \times \mathcal{Z}, \mu)$, we define its {\em maximal correlation} $\rho(\mathcal{Z} \times \mathcal{Z}; \mu)$ (or simply $\rho(\mu)$) as follows,
	\[ \rho(\mathcal{Z} \times \mathcal{Z}; \mu) ~=~ \sup_{f, g} \set{\inangle{f,g}_{\mu} \ \ \bigg | \ \ \inmat{f : \mathcal{Z} \to {\mathbb R}, & \mathbb{E}[f] = \mathbb{E}[g]= 0\\ g : \mathcal{Z} \to {\mathbb R}, & \mathsf{Var}(f) = \mathsf{Var}(g) = 1}} \]

\label{def:rounding_op}
	The {\em Rounding operator} $\mathcal{R}^{(k)} : {\mathbb R}^k \to \Delta_k$ maps any ${\bm v} \in {\mathbb R}^k$ to its closest point in $\Delta_k$. In particular, it is the identity map on $\Delta_k$. We will drop the superscript, as $k$ is fixed throughout this paper.

	As for vector-valued functions, we use $\mathcal{R}_i$ to denote the $i$-th coordinate of $\mathcal{R}$. Thus, while the $i$-th coordinate of $A$ is denoted by $A_i$, the $i$-th coordinate of $\mathcal{R}(A)$ is denoted by $\mathcal{R}_i(A)$.

The proof follows very easily from the Cauchy-Schwarz inequality. In particular,
\begin{align*}



\inabs{\inangle{\wtilde{A}, \wtilde{B}}_{\mu^{\otimes n}} - \inangle{A, B}_{\mu^{\otimes n}}}
&~=~ \inabs{\inangle{(\wtilde{A} - A), \ \wtilde{B}}_{\mu^{\otimes n}} + \inangle{A,\ (\wtilde{B} - B)}_{\mu^{\otimes n}}}\\
&~\le~ \inabs{\inangle{(\wtilde{A} - A), \ \wtilde{B}}_{\mu^{\otimes n}}} + \inabs{\inangle{A,\ (\wtilde{B} - B)}_{\mu^{\otimes n}}}\\
&~\le~ \norm{2}{\wtilde{A} - A} \cdot \norm{2}{\wtilde{B}} + \norm{2}{\wtilde{B} - B} \cdot \norm{2}{A} \qquad \ldots \text{(Cauchy-Schwarz inequality)}\\
&~\le~ 2\varepsilon\;. \qedhere
\end{align*}

\begin{align*}



	\inabs{\inangle{\wtilde{A}, \wtilde{B}}_{\mu^{\otimes n}} - \inangle{A, B}_{\mu^{\otimes n}}}
	&~=~ \inabs{\inangle{(\wtilde{A} - A), \ \wtilde{B}}_{\mu^{\otimes n}} + \inangle{A,\ (\wtilde{B} - B)}_{\mu^{\otimes n}}}\\
	&~\le~ \inabs{\inangle{(\wtilde{A} - A), \ \wtilde{B}}_{\mu^{\otimes n}}} + \inabs{\inangle{A,\ (\wtilde{B} - B)}_{\mu^{\otimes n}}}\\
	&~\le~ \norm{2}{\wtilde{A} - A} \cdot \norm{2}{\wtilde{B}} + \norm{2}{\wtilde{B} - B} \cdot \norm{2}{A} \qquad \ldots \text{(Cauchy-Schwarz inequality)}\\
	&~\le~ 2\varepsilon\;. \qedhere
	\end{align*}

The proof follows very easily from a triangle inequality. In particular,
\begin{align*}
\norm{2}{\mathcal{R}(\wtilde{A}) - \wtilde{A}}
&~\le~ \norm{2}{\mathcal{R}(A) - \wtilde{A}} && \text{(since $\mathcal{R}(\wtilde{A}({\bm x}))$ closest in $\Delta_k$ to $\wtilde{A}({\bm x})$)}\\
&~\le~ \norm{2}{\mathcal{R}(A) - A} + \norm{2}{A - \wtilde{A}} && \text{(Triangle inequality)} \qedhere
\end{align*}

\begin{align*}
	\norm{2}{\mathcal{R}(\wtilde{A}) - \wtilde{A}}
	&~\le~ \norm{2}{\mathcal{R}(A) - \wtilde{A}} && \text{(since $\mathcal{R}(\wtilde{A}({\bm x}))$ closest in $\Delta_k$ to $\wtilde{A}({\bm x})$)}\\
	&~\le~ \norm{2}{\mathcal{R}(A) - A} + \norm{2}{A - \wtilde{A}} && \text{(Triangle inequality)} \qedhere
	\end{align*}

