{\em (Bound on Mean \& Variance).}\label{lem:mean_var_bound}
	Given parameters $d$ and $\delta$, there exists $D := D(d, \delta)$ such that the following holds: For $M \sim \mathcal{N}(0,1)^{\otimes (N \times D)}$,
	\begin{align*}
	\inabs{\mathbb{E}\limits_{M} F(M) - \inangle{A, B}_{\mathcal{G}_{\rho}^{\otimes N}}} &~\le~ \delta \qquad \text{\bf (Mean bound)}\\
	\mathsf{Var}_M \inparen{F(M)} &~\le~ \delta \qquad \text{\bf (Variance bound)}
	\end{align*}
	In particular, one may take $D = \frac{d^{O(d)}}{\delta^2}$.

\begin{align*}
	\inabs{\mathbb{E}\limits_{M} F(M) - \inangle{A, B}_{\mathcal{G}_{\rho}^{\otimes N}}} &~\le~ \delta \qquad \text{\bf (Mean bound)}\\
	\mathsf{Var}_M \inparen{F(M)} &~\le~ \delta \qquad \text{\bf (Variance bound)}
	\end{align*}

\begin{align*}
		&\Pr_M \insquare{\inabs{F(M) - \inangle{A, B}_{\mathcal{G}_{\rho}^{\otimes N}}} > \delta}\\
		& ~\le~ \Pr_M \insquare{\inabs{F(M) - \mathbb{E}_M F(M)} + \inabs{\mathbb{E}_M F(M) - \inangle{A, B}_{\mathcal{G}_{\rho}^{\otimes N}}} > \delta}\\
		& ~\le~ \Pr_M \insquare{\inabs{F(M) - \mathbb{E}_M F(M)} > \delta - \delta^2}\\
		& ~\le~ \delta.\qedhere
	\end{align*}

 \label{lem:smoothing_main}
	Let $\rho \in [0,1]$, $\delta > 0$, $k \in {\mathbb N}$ be any given constant parameters. There exists an explicit $d = d(\rho, k, \delta)$ such that the following holds:\\

	\noindent {\bf (Correlated Discrete Hypercube):} Let $(\mathcal{Z} \times \mathcal{Z}, \mu)$ be a joint probability space, with $\rho(\mathcal{Z}, \mathcal{Z}; \mu) = \rho$. Let $A : \mathcal{Z}^n \to {\mathbb R}^k$ and $B : \mathcal{Z}^n \to {\mathbb R}^k$, such that, for any $j \in [k]$ : $\mathsf{Var}(A_j), \mathsf{Var}(B_j) \le 1$.\\
	Then, there exist functions $A^{(1)} : \mathcal{Z}^n \to {\mathbb R}^k$ and $B^{(1)} : \mathcal{Z}^n \to {\mathbb R}^k$ such that statements 1-4 below hold.\\

	\noindent {\bf (Correlated Gaussian):} Let $A : {\mathbb R}^n \to {\mathbb R}^k$ and $B : {\mathbb R}^n \to {\mathbb R}^k$, such that, for any $j \in [k]$ : $\mathsf{Var}(A_j), \mathsf{Var}(B_j) \le 1$.\\
	Then, there exist functions $A^{(1)} : {\mathbb R}^n \to {\mathbb R}^k$ and $B^{(1)} : {\mathbb R}^n \to {\mathbb R}^k$ such that statements 1-4 below hold.

	\begin{enumerate}
	\item $A^{(1)}$ and $B^{(1)}$ have degree at most $d$.
	\item For any $i \in [k]$, it holds that $\mathsf{Var}(A^{(1)}_i) \le \mathsf{Var}(A_i) \le 1$ and $\mathsf{Var}(B^{(1)}_i) \le \mathsf{Var}(B_i) \le 1$.
	\item $\norm{2}{\mathcal{R}(A^{(1)}) - A^{(1)}} ~\le~ \norm{2}{\mathcal{R}(A) - A} + \delta$ and $\norm{2}{\mathcal{R}(B^{(1)}) - B^{(1)}} ~\le~ \norm{2}{\mathcal{R}(B) - B} + \delta$
	\item For every $i, j \in [k]$,
	\begin{align*}
		& \inabs{\inangle{A^{(1)}_i, B^{(1)}_j}_{\mu^{\otimes n}} - \inangle{A_i, B_j}_{\mu^{\otimes n}}} ~\le~ \frac{\delta}{\sqrt{k}} && \text{\bf (Correlated Discrete Hypercube)} \\
		& \inabs{\inangle{A^{(1)}_i, B^{(1)}_j}_{\mathcal{G}_\rho^{\otimes n}} - \inangle{A_i, B_j}_{\mathcal{G}_\rho^{\otimes n}}} ~\le~ \frac{\delta}{\sqrt{k}} && \text{\bf (Correlated Gaussian)}
	\end{align*}


	\end{enumerate}

	\noindent In particular, one may take $d = O\inparen{\frac{\sqrt{k}\log^2 (k/\delta)}{\delta (1 - \rho)}}$.

\begin{align*}
		& \inabs{\inangle{A^{(1)}_i, B^{(1)}_j}_{\mu^{\otimes n}} - \inangle{A_i, B_j}_{\mu^{\otimes n}}} ~\le~ \frac{\delta}{\sqrt{k}} && \text{\bf (Correlated Discrete Hypercube)} \\
		& \inabs{\inangle{A^{(1)}_i, B^{(1)}_j}_{\mathcal{G}_\rho^{\otimes n}} - \inangle{A_i, B_j}_{\mathcal{G}_\rho^{\otimes n}}} ~\le~ \frac{\delta}{\sqrt{k}} && \text{\bf (Correlated Gaussian)}
	\end{align*}

\label{cor:noise-stability}
	Given parameters $k \ge 2$, $\rho \in [0,1]$ and $\varepsilon > 0$, there exists an explicitly computable $n_0 = n_0(\rho, k, \varepsilon)$ such that the following holds:

	Let $f : {\mathbb R}^N \to [k]$. Then, there exists a function $\wtilde{f} : {\mathbb R}^{n_0} \to \Delta_k$ such that
	\begin{enumerate}
		\item $\norm{1}{\mathbb{E}[f] - \mathbb{E}[\wtilde{f}]} \le \varepsilon$.
		\item $\mathbb{E}\insquare{\inangle{\wtilde{f}, U_\rho \wtilde{f}}} \ge \mathbb{E}[\inangle{f, U_\rho f}] - \varepsilon$.
	\end{enumerate}
	Moreover, there exists $d_0 = d_0(\rho, k, \varepsilon)$ for which there is a degree-$d_0$ polynomial $g : {\mathbb R}^{n_0} \to {\mathbb R}^k $, such that, $\wtilde{f}({\bm a}) = \mathcal{R}\inparen{g\inparen{\frac{{\bm a}}{\|{\bm a}\|_2}}}$. In particular, one may take $n_0 = \exp \inparen{\mathrm{poly}\inparen{k, \frac{1}{\varepsilon}, \frac{1}{1-\rho}}}$ and $d_0 = \mathrm{poly}\inparen{k, \frac{1}{\varepsilon}, \frac{1}{1-\rho}}$.

For any $i, j \in [k]$, we focus on the quantity $\inangle{A_i, B_j}_{\mathcal{G}_\rho^{\otimes n}}$ which is the probability of the event that [{\em Alice outputs $i$ and Bob outputs $j$}]. Through several steps, we modify Alice's and Bob's strategies, while approximately preserving this quantity for every $i, j$. Note that if we preserve the probability that Alice outputs $i$ and Bob outputs $j$ for every $i, j$ upto an additive $\varepsilon/k^2$, this implies that we would preserve the joint distribution of Alice and Bob's outputs up to $\ell_1$-distance of $\varepsilon$.


