We transform $A$ and $B$ through each of the following steps, as illustrated in \Cref{fig:Gaussian_NIS}. At each step, we approximately preserve the correlation $\inangle{A_i, B_j}$ for every $i, j \in [k]$. Additionally, in each step $\norm{2}{\mathcal{R}(A) - A}$ and $\norm{2}{\mathcal{R}(B) - B}$ also doesn't increase significantly. Note that, to begin with the range of $A$ and $B$ is $\Delta_k$ and hence $\norm{2}{\mathcal{R}(A) - A} = \norm{2}{\mathcal{R}(B) - B} = 0$.

\begin{enumerate}
	\item {\bf Smoothing}: We apply \Cref{lem:smoothing_main} with parameter $\delta$, setting $d = d(\rho, k, \delta)$ as required, on $A$ and $B$ to get the smoothened versions $A^{(1)} : {\mathbb R}^N \to {\mathbb R}^k$ and $B^{(1)} : {\mathbb R}^N \to {\mathbb R}^k$. This guarantees that $A^{(1)}$ and $B^{(1)}$ have degree at most $d$. Moreover, we have that for every $i, j \in [k]$,
	\begin{equation}
	\inabs{\inangle{A^{(1)}_i, B^{(1)}_j}_{\mathcal{G}_\rho^{\otimes N}} - \inangle{A_i, B_j}_{\mathcal{G}_\rho^{\otimes N}}} \le \delta \label{eqn:GNIS-1}
	\end{equation}
	Additionally,
	\[ \norm{2}{\mathcal{R}(A^{(1)}) - A^{(1)}} ~\le~ \norm{2}{\mathcal{R}(A) - A} + \delta ~\le~ \delta\;.\]
	Similarly, we also have that,
	\[\norm{2}{\mathcal{R}(B^{(1)}) - B^{(1)}} ~\le~ \delta\]

	\item {\bf Multilinearization}: We apply \Cref{lem:multilin_main} with parameter $\delta$, setting $t = t(d, k, \delta)$ as required, on $A^{(1)}$ and $B^{(1)}$ to get the multilinearized versions $A^{(2)} : {\mathbb R}^{Nt} \to {\mathbb R}^k$ and $B^{(2)} : {\mathbb R}^{Nt} \to {\mathbb R}^k$. This guarantees that both $A^{(2)}$ and $B^{(2)}$ are multilinear and have degree at most $d$, albeit over a slightly larger number of variables. We get,
	\begin{equation}
	\inabs{\inangle{A^{(2)}_i, B^{(2)}_j}_{\mathcal{G}_\rho^{\otimes Nt}} - \inangle{A^{(1)}_i, B^{(1)}_j}_{\mathcal{G}_\rho^{\otimes N}}} \le \delta \label{eqn:GNIS-2}
	\end{equation}


	Additionally,
	\[ \norm{2}{\mathcal{R}(A^{(2)}) - A^{(2)}} ~\le~ \norm{2}{\mathcal{R}(A^{(1)}) - A^{(1)}} + \delta ~\le~ 2\delta\]
	Similarly, we also have that,
	\[ \norm{2}{\mathcal{R}(B^{(2)}) - B^{(2)}} ~\le~ 2 \delta\]

	\item {\bf Dimension reduction}: We apply \Cref{thm:dim-reduction} with parameter $\delta/k^2$, setting $D = D(d, \rho, \delta/k^2)$ as required, on individual coordinates of $A^{(2)}$ and $B^{(2)}$ to obtain functions $A^{(3)} : {\mathbb R}^D \to {\mathbb R}^k$ and $B^{(3)} : {\mathbb R}^D \to {\mathbb R}^k$. Taking a union bound, we have that with probability at least $1-\delta$, it holds for every $i, j \in [k]$ that, 
	\begin{equation}
	\inabs{\inangle{A^{(3)}_i, B^{(3)}_j}_{\mathcal{G}_\rho^{\otimes D}} - \inangle{A^{(2)}_i, B^{(2)}_j}_{\mathcal{G}_\rho^{\otimes Nt}}} \le \delta \label{eqn:GNIS-3}
	\end{equation}
	From \Cref{prop:dim-red-close-to-simplex}, we have that with probability $1-4\delta$,
	\[ \norm{2}{\mathcal{R}(A^{(3)}) - A^{(3)}} ~\le~ \sqrt{\norm{2}{\mathcal{R}(A^{(2)}) - A^{(2)}}} ~\le~ \sqrt{2\delta}\]
	\[\norm{2}{\mathcal{R}(B^{(3)}) - B^{(3)}} ~\le~ \sqrt{\norm{2}{\mathcal{R}(B^{(1)}) - B^{(1)}}} ~\le~ \sqrt{2\delta}\]

	Note that this is the only randomized procedure in the entire transformation. This reduction succeeds in obtaining the three constraints above with probability at least $1 - 5\delta$.

	\item {\bf Rounding to $\Delta_k$}: We obtain our final functions as $\wtilde{A} = \mathcal{R}(A^{(3)})$ and $\wtilde{B} = \mathcal{R}(B^{(3)})$. 
	Note that $\norm{2}{\mathcal{R}(A^{(3)}) - A^{(3)}}, \norm{2}{\mathcal{R}(B^{(3)}) - B^{(3)}} \le \sqrt{2\delta}$, and hence we have for any $i, j \in [k]$ that \[\norm{2}{\wtilde{A}_i - A_i^{(3)}} \le \sqrt{2 \delta} \qquad \ \mathrm{and} \ \qquad \norm{2}{\wtilde{B}_j - B_j^{(3)}} \le \sqrt{2\delta}\;.\]
	Hence we can invoke \Cref{lem:close-strategies}, to conclude that for $\wtilde{A} = \mathcal{R}(A^{(3)})$ and $\wtilde{B} = \mathcal{R}(B^{(3)})$,
	\begin{equation}
	\inabs{\inangle{\wtilde{A}_i, \wtilde{B}_j}_{\mathcal{G}_\rho^{\otimes D}} - \inangle{A^{(3)}_i, B^{(3)}_j}_{\mathcal{G}_\rho^{\otimes D}}} ~\le~ 2 \sqrt{\delta}. \label{eqn:GNIS-4}
	\end{equation}
\end{enumerate}

\noindent Finally, we choose $n_0 = D$ and $d_0 = d$ as obtained above. Note that we started with functions $A: {\mathbb R}^N \to \Delta_k$ and $B : {\mathbb R}^N \to \Delta_k$ and we ended with functions $\wtilde{A} : {\mathbb R}^{n_0} \to \Delta_k$ and $\wtilde{B} : {\mathbb R}^{n_0} \to \Delta_k$ such that for every $i, j \in [k]$, we have by combining \Cref{eqn:GNIS-1,eqn:GNIS-2,eqn:GNIS-3,eqn:GNIS-4} that,
\[ \inabs{\inangle{\wtilde{A}_i, \wtilde{B}_j}_{\mathcal{G}_\rho^{\otimes D}} - \inangle{A_i, B_j}_{\mathcal{G}_\rho^{\otimes N}}} ~\le~ O(\sqrt{\delta})\]

\noindent Thus, more strongly, if we instantiate $\delta = O(\varepsilon^2/k^4)$, then we get that our entire transformation succeeds with probability $1-\varepsilon$ in obtaining $\wtilde{A}$ and $\wtilde{B}$ such that,
\[d_{\mathrm{TV}}((A(\mathbf{X}),B(\mathbf{Y}))_{\mathbf{X},\mathbf{Y}}, (\wtilde{A}({\bm a}), \wtilde{B}({\bm b}))_{{\bm a}, {\bm b}}) \le \varepsilon\;,\]
where recall that $(\mathbf{X}, \mathbf{Y}) \sim \mathcal{G}_\rho^{\otimes N}$ and $({\bm a}, {\bm b}) \sim \mathcal{G}_\rho^{\otimes n_0}$. It is easy to see that the parameters work out to be
\[ d_0 = d = \wtilde{O}\inparen{\frac{k^{4.5}}{\varepsilon^2 (1-\rho)}}\;, \]
\[ n_0 = D = \frac{d^{O(d)}}{\delta^4} = \exp\inparen{\wtilde{O}\inparen{\frac{k^{4.5}}{\varepsilon^2 (1-\rho)}}}\;.\]

\begin{equation}
	\inabs{\inangle{A^{(1)}_i, B^{(1)}_j}_{\mathcal{G}_\rho^{\otimes N}} - \inangle{A_i, B_j}_{\mathcal{G}_\rho^{\otimes N}}} \le \delta \label{eqn:GNIS-1}
	\end{equation}

\begin{equation}
	\inabs{\inangle{A^{(2)}_i, B^{(2)}_j}_{\mathcal{G}_\rho^{\otimes Nt}} - \inangle{A^{(1)}_i, B^{(1)}_j}_{\mathcal{G}_\rho^{\otimes N}}} \le \delta \label{eqn:GNIS-2}
	\end{equation}

\begin{equation}
	\inabs{\inangle{A^{(3)}_i, B^{(3)}_j}_{\mathcal{G}_\rho^{\otimes D}} - \inangle{A^{(2)}_i, B^{(2)}_j}_{\mathcal{G}_\rho^{\otimes Nt}}} \le \delta \label{eqn:GNIS-3}
	\end{equation}

\begin{equation}
	\inabs{\inangle{\wtilde{A}_i, \wtilde{B}_j}_{\mathcal{G}_\rho^{\otimes D}} - \inangle{A^{(3)}_i, B^{(3)}_j}_{\mathcal{G}_\rho^{\otimes D}}} ~\le~ 2 \sqrt{\delta}. \label{eqn:GNIS-4}
	\end{equation}

{\Cref{thm:non-int-sim}}
As in the proof of \Cref{thm:gaussian-non-int-sim}, for any $i, j \in [k]$, we focus on the quantity $\inangle{A_i, B_j}_{\mu^{\otimes n}}$ which is the probability of the event that [{\em Alice outputs $i$ and Bob outputs $j$}]. Through the several steps we modify Alice's and Bob's strategy, while preserving this quantity approximately for every $i, j$. If we preserve the probability that Alice outputs $i$ and Bob outputs $j$ for every $i, j$ upto an additive $\varepsilon/k^2$, it implies that we preserve the joint distribution of Alice and Bob's outputs up to an $\ell_1$-distance of $\varepsilon$.


