\begin{enumerate}
	\item {\bf Smoothing (over hypercube)}: We apply \Cref{lem:smoothing_main} on $A$ and $B$ to get the low-degree versions $A^{(1)} : \mathcal{Z}^N \to {\mathbb R}^k$ and $B^{(1)} : \mathcal{Z}^N \to {\mathbb R}^k$. This guarantees that $A^{(1)}$ and $B^{(1)}$ have degree at most $d$. Moreover, we have that for every $i, j \in [k]$,
	\[ \inabs{\inangle{A^{(1)}_i, B^{(1)}_j}_{\mu^{\otimes N}} - \inangle{A_i, B_j}_{\mu^{\otimes N}}} \le \delta \]
	Additionally,
	\[ \norm{2}{\mathcal{R}(A^{(1)}) - A^{(1)}} ~\le~ \norm{2}{\mathcal{R}(A) - A} + \delta ~\le~ \delta\;.\]
	Similarly, we also have that,
	\[\norm{2}{\mathcal{R}(B^{(1)}) - B^{(1)}} ~\le~ \delta\]
	Using \Cref{lem:close-strategies}, we can conclude that for every $i, j \in [k]$,
	\begin{equation}
	\inabs{\inangle{\mathcal{R}_i(A^{(1)}), \mathcal{R}_j(B^{(1)})}_{\mu^{\otimes N}} - \inangle{A_i, B_j}_{\mu^{\otimes N}}} ~\le~ 3\delta \label{eqn:NIS-1}
	\end{equation}



	\item {\bf Regularity Lemma}:  We apply \Cref{lem:joint_regularity} to identify a subset $H \subseteq [n]$ with $|H| = h$, such that, for a random restriction $({\bm x}_H, {\bm y}_H) \sim \mu^{\otimes h}$, it holds with probability at least $1-\tau$, that the restricted functions $(A^{(1)}_i)^{{\bm x}_H} : \mathcal{Z}^{N-h} \to {\mathbb R}^k$ and $(B^{(1)}_i)^{{\bm y}_H} : \mathcal{Z}^{N-h} \to {\mathbb R}^k$ have all individual influences smaller than $\tau$, for any $i \in [k]$. We call a restriction $({\bm x}_H, {\bm y}_H)$ as ``{\em good}'' in this case, and ``{\em bad}'' otherwise. Note that any such restriction (``good'' or ``bad'') has degree at most $d$.


	For the rest of the steps, we will focus on a {\em good} $({\bm x}_H, {\bm y}_H)$. For convenience, define $N_1 = N-h$.

	\item {\bf Invariance Principle (from $\mathcal{Z}$ to ${\mathbb R}$)}: For a {\em good} $({\bm x}_H, {\bm y}_H)$, we apply \Cref{lem:our_invariance} on $(A^{(1)})^{{\bm x}_H}$ and $(B^{(1)})^{{\bm y}_H}$ to get functions $(A^{(2)})^{{\bm x}_H} : {\mathbb R}^{N_2} \to \Delta_k$ and $(B^{(2)})^{{\bm y}_H} : {\mathbb R}^{N_2} \to \Delta_k$ (where $N_2 = N_1 \cdot (q-1)$), such that for every $i, j \in [k]$,

	\begin{equation}
		\inabs{\inangle{(A^{(2)}_i)^{{\bm x}_H}, (B^{(2)}_j)^{{\bm y}_H}}_{\mathcal{G}_\rho^{\otimes N_2}} - \inangle{\mathcal{R}_i\inparen{(A^{(1)})^{{\bm x}_H}}, \mathcal{R}_j\inparen{(B^{(1)})^{{\bm y}_H}}}_{\mu^{\otimes N_1}}} ~\le~ \delta \label{eqn:NIS-2}
	\end{equation}
	Note that strictly speaking \Cref{lem:our_invariance}, as stated, gives us functions mapping to ${\mathbb R}^k$ and not $\Delta_k$. However, we consider their rounded versions, which exactly gives us the statement above.

	\item {\bf Dimension Reduction}: We apply \Cref{thm:dim-reduction} on $(A^{(2)})^{{\bm x}_H}$ and $(B^{(2)})^{{\bm y}_H}$, to get functions $(A^{(3)})^{{\bm x}_H} : {\mathbb R}^D \to \Delta_k$ and $(B^{(3)})^{{\bm y}_H} : {\mathbb R}^D \to \Delta_k$, such that, for every $i, j \in [k]$,
	\begin{equation}
		\inabs{\inangle{(A^{(3)}_i)^{{\bm x}_H}, (B^{(3)}_j)^{{\bm y}_H}}_{\mathcal{G}_\rho^{\otimes D}} - \inangle{(A^{(2)}_i)^{{\bm x}_H}, (B^{(2)}_j)^{{\bm y}_H}}_{\mathcal{G}_\rho^{\otimes N_2}}} ~\le~ \delta \label{eqn:NIS-3}
	\end{equation}
	Note that this is the only randomized step in the entire transformation. This reduction succeeds with probability at least $1 - 4\delta$ for every {\em good} $({\bm x}_H, {\bm y}_H)$. For a fixed choice of the random seed, we call a {\em good} $({\bm x}_H, {\bm y}_H)$ as ``{\em lucky}''\footnote{rather poor choice of terminology, given that most $({\bm x}_H, {\bm y}_H)$ end up being {\em lucky}!} if the reduction succeeds for that $({\bm x}_H, {\bm y}_H)$. In expectation over the choice of random seeds, a $(1-4\delta)$ fraction of the {\em good} $({\bm x}_H, {\bm y}_H)$ are going to be {\em lucky}. We can hence choose a choice of random seed for which indeed a $(1-4\delta)$ fraction of the {\em good} $({\bm x}_H, {\bm y}_H)$ are {\em lucky}.

	On the other hand, Regularity Lemma ensures that with probability $1-\delta$, a sampled $({\bm x}_H, {\bm y}_H)$ will be {\em good}. This gives that for the said choice of random seed in \Cref{thm:gaussian-non-int-sim}, with probability at least $1-5\delta$, the sampled $({\bm x}_H, {\bm y}_H)$ is both {\em good} and {\em lucky}. For the rest of the steps, we will focus on a {\em good} and {\em lucky} $({\bm x}_H, {\bm y}_H)$.

	\item {\bf Smoothing (over Gaussian space)}: We again apply \Cref{lem:smoothing_main} on $(A^{(3)})^{{\bm x}_H}$ and $(B^{(3)})^{{\bm y}_H}$ to get the low-degree versions $(A^{(4)})^{{\bm x}_H} : {\mathbb R}^D \to {\mathbb R}^k$ and $(B^{(4)})^{{\bm y}_H} : {\mathbb R}^D \to {\mathbb R}^k$. This guarantees that $(A^{(4)})^{{\bm x}_H}$ and $(B^{(4)})^{{\bm y}_H}$ have degree at most $d$. Moreover, we have that for every $i, j \in [k]$,
	\begin{equation}
	\inabs{\inangle{(A^{(4)}_i)^{{\bm x}_H}, (B^{(4)}_j)^{{\bm y}_H}}_{\mathcal{G}_\rho^{\otimes D}} - \inangle{(A^{(3)}_i)^{{\bm x}_H}, (B^{(3)}_j)^{{\bm y}_H}}_{\mathcal{G}_\rho^{\otimes D}}} ~\le~ \delta \label{eqn:NIS-4}
	\end{equation}
	Additionally,
	\[ \norm{2}{\mathcal{R}(A^{(4)}) - A^{(4)}} ~\le~ \delta \qquad \ \mathrm{and} \ \qquad \norm{2}{\mathcal{R}(B^{(4)}) - B^{(4)}} ~\le~ \delta \]





	\item {\bf Multilinearization}: We apply \Cref{lem:multilin_main} on $(A^{(4)})^{{\bm x}_H}$ and $(B^{(4)})^{{\bm y}_H}$ to get the multilinearized and low-influential versions $(A^{(5)})^{{\bm x}_H} : {\mathbb R}^{D_1} \to {\mathbb R}^k$ and $(B^{(5)})^{{\bm y}_H} : {\mathbb R}^{D_1} \to {\mathbb R}^k$ (where $D_1 = Dt$). Thus, we have for every $i, j \in [k]$,
	\[ \inabs{\inangle{(A^{(5)}_i)^{{\bm x}_H}, (B^{(5)}_j)^{{\bm y}_H}}_{\mathcal{G}_\rho^{\otimes D_1}} - \inangle{(A^{(4)}_i)^{{\bm x}_H}, (B^{(4)}_j)^{{\bm y}_H}}_{\mathcal{G}_\rho^{\otimes D}}} ~\le~ \delta \]
	Additionally, combining with \Cref{lem:close-to-simplex},
	\[ \norm{2}{\mathcal{R}(A^{(5)}) - A^{(5)}} ~\le~ \norm{2}{\mathcal{R}(A^{(4)}) - A^{(4)}} + \norm{2}{A^{(5)} - A^{(4)}} ~\le~ 2\delta \]
	Similarly,
	\[ \norm{2}{\mathcal{R}(B^{(5)}) - B^{(5)}} ~\le~ 2\delta \]
	Combining all this with \Cref{lem:close-strategies} we get that,
	\begin{equation}
	\inabs{\inangle{\mathcal{R}_i\inparen{(A^{(5)})^{{\bm x}_H}}, \mathcal{R}_j\inparen{(B^{(5)})^{{\bm y}_H}}}_{\mathcal{G}_\rho^{\otimes D_1}} - \inangle{(A^{(4)}_i)^{{\bm x}_H}, (B^{(4)}_j)^{{\bm y}_H}}_{\mathcal{G}_\rho^{\otimes D}}} ~\le~ 5\delta \label{eqn:NIS-5}
	\end{equation}
	Additionally, note that we also have that $\mathrm{Inf}_\ell((A^{(5)}_i))^{{\bm x}_H} \le \tau$ and $\mathrm{Inf}_\ell((B^{(5)}_i))^{{\bm y}_H} \le \tau$ for all $i \in [k]$ and $\ell \in [n]$. This is helpful for us to apply the invariance principle next.

	\item {\bf Invariance Principle (from ${\mathbb R}$ to $\mathcal{Z}$)}: We apply \Cref{lem:our_invariance} on $(A^{(5)})^{{\bm x}_H}$ and $(B^{(5)})^{{\bm y}_H}$ to get functions $(A^{(6)})^{{\bm x}_H} : \mathcal{Z}^{D_1} \to \Delta_k$ and $(B^{(6)})^{{\bm y}_H} : \mathcal{Z}^{D_1} \to \Delta_k$, such that for every $i, j \in [k]$,

	\begin{equation}
	\inabs{\inangle{(A^{(6)}_i)^{{\bm x}_H}, (B^{(6)}_j)^{{\bm y}_H}}_{\mu^{\otimes D_1}} - \inangle{\mathcal{R}_i\inparen{(A^{(5)})^{{\bm x}_H}}, \mathcal{R}_j\inparen{(B^{(5)})^{{\bm y}_H}}}_{\mathcal{G}_\rho^{\otimes D_1}}} ~\le~ \delta \label{eqn:NIS-6}
	\end{equation}
	Note again that strictly speaking \Cref{lem:our_invariance} gives us functions mapping to ${\mathbb R}^k$ and not $\Delta_k$. However, we consider their rounded versions, which exactly gives us the statement above.







\end{enumerate}

\paragraph{Putting it together.} We now show how to put together \Cref{eqn:NIS-1,eqn:NIS-2,eqn:NIS-3,eqn:NIS-4,eqn:NIS-5,eqn:NIS-6} to get our final conclusion. We now define our final functions $\wtilde{A} : \mathcal{Z}^{n_0} \to \Delta_k$ and $\wtilde{B} : \mathcal{Z}^{n_0} \to \Delta_k$ as follows. Firstly, we interpret the $n_0 = h + D_1$ coordinates of ${\bm x}$ as two parts: {\em head} coordinates ${\bm x}_H \in \mathcal{Z}^h$ and the remaining coordinates ${\bm x}_R \in \mathcal{Z}^{D_1}$. Similarly for ${\bm y}$.
\[ \wtilde{A}({\bm x}) = \wtilde{A}({\bm x}_H, {\bm x}_R) = (A^{(6)})^{{\bm x}_H}({\bm x}_R) \qquad \ \mathrm{and} \ \qquad \wtilde{B}({\bm y}) = \wtilde{B}({\bm y}_H, {\bm y}_R) = (B^{(6)})^{{\bm y}_H}({\bm y}_R)\;.\]
We now show that for all $i, j \in [k]$, it holds that,
\[ 	\inabs{\inangle{\wtilde{A}_i, \wtilde{B}_j}_{\mu^{\otimes n_0}} - \inangle{A_i, B_j}_{\mu^{\otimes N}}} ~\le~ O(\delta) \]
We note that,
\begin{align*}
& \inangle{\wtilde{A}_i, \wtilde{B}_j}_{\mu^{\otimes n_0}} \\
&~=~ \mathbb{E}_{({\bm x}_H, {\bm y}_H) \sim \mu^{\otimes h}} \inangle{(A^{(6)}_i)^{{\bm x}_H}, (B^{(6)}_j)^{{\bm y}_H}}_{\mu^{\otimes D_1}}\\
&~=~ \Pr\inbmat{\text{$({\bm x}_H, {\bm y}_H)$ is} \\ \text{({\em good} and {\em lucky})}} \cdot \mathbb{E}_{\substack{({\bm x}_H, {\bm y}_H) \sim \mu^{\otimes h}\\ | \ \text{{\em good} \& {\em lucky}}}} \inangle{(A^{(6)}_i)^{{\bm x}_H}, (B^{(6)}_j)^{{\bm y}_H}}_{\mu^{\otimes D_1}}\\
& \quad ~+~ \Pr\inbmat{\text{$({\bm x}_H, {\bm y}_H)$ is not} \\ \text{({\em good} and {\em lucky})}} \cdot \mathbb{E}_{\substack{({\bm x}_H, {\bm y}_H) \sim \mu^{\otimes h}\\ | \ \text{not ({\em good} \& {\em lucky})}}} \inangle{(A^{(6)}_i)^{{\bm x}_H}, (B^{(6)}_j)^{{\bm y}_H}}_{\mu^{\otimes D_1}}\\
&~=~ \Pr\inbmat{\text{$({\bm x}_H, {\bm y}_H)$ is} \\ \text{({\em good} and {\em lucky})}} \cdot \mathbb{E}_{\substack{({\bm x}_H, {\bm y}_H) \sim \mu^{\otimes h}\\ | \ \text{{\em good} \& {\em lucky}}}} \inangle{(A^{(6)}_i)^{{\bm x}_H}, (B^{(6)}_j)^{{\bm y}_H}}_{\mu^{\otimes D_1}} ~\pm~ O(\delta)\\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \ldots \inparen{\text{since } \Pr\inbmat{\text{$({\bm x}_H, {\bm y}_H)$ is not} \\ \text{({\em good} and {\em lucky})}} \le O(\delta)}\\
&~=~ \Pr\inbmat{\text{$({\bm x}_H, {\bm y}_H)$ is} \\ \text{({\em good} and {\em lucky})}} \cdot \mathbb{E}_{\substack{({\bm x}_H, {\bm y}_H) \sim \mu^{\otimes h}\\ | \ \text{{\em good} \& {\em lucky}}}} \inangle{\mathcal{R}_i\inparen{(A^{(1)})^{{\bm x}_H}}, \mathcal{R}_j\inparen{(B^{(1)})^{{\bm y}_H}}}_{\mu^{\otimes N_1}} ~\pm~ O(\delta)\\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \ldots \inparen{\inmat{\text{combining \Cref{eqn:NIS-2,eqn:NIS-3,eqn:NIS-4,eqn:NIS-5,eqn:NIS-6}}\\ \text{which hold for {\em good} and {\em lucky} } ({\bm x}_H,{\bm y}_H)}}\\
&~=~ \mathbb{E}_{({\bm x}_H, {\bm y}_H) \sim \mu^{\otimes h}} \inangle{\mathcal{R}_i\inparen{(A^{(1)})^{{\bm x}_H}}, \mathcal{R}_j\inparen{(B^{(1)})^{{\bm y}_H}}}_{\mu^{\otimes N_1}} ~\pm~ O(\delta)\\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \ldots \inparen{\text{since } \Pr\inbmat{\text{$({\bm x}_H, {\bm y}_H)$ is} \\ \text{({\em good} and {\em lucky})}} \in [1-O(\delta), \ 1]}\\
&~=~ \inangle{\mathcal{R}_i(A^{(1)}), \mathcal{R}_j(B^{(1)})}_{\mu^{\otimes N}} ~\pm~ O(\delta)\\
&~=~ \inangle{A_i, B_j}_{\mu^{\otimes N}} ~\pm~ O(\delta) \qquad \qquad \quad \ldots\text{(using \Cref{eqn:NIS-1})}
\end{align*}



