\label{prop:inv_chi_mom_dist}
	There exists an absolute constant $C$ such that for sufficiently large $d, D \in {\mathbb Z}_{> 0}$, such that $D > Cd^2$, we have that for ${\bm w} \sim \gamma_D$,
	\begin{align}
	\bigg| \mathbb{E}_{{\bm w}}\bigg[\frac{1}{\|{\bm w}\|_2^d}\bigg] - \frac{1}{D^{d/2}} \bigg| &~\le~ C \cdot \inparen{\frac{d^2}{D^{\frac{d}{2}+1}}}, \label{eq:mean_univ_bd}\\
	\mathsf{Var}_{{\bm w}}\bigg[ \frac{1}{\| {\bm w} \|_2^d}\bigg] &~\le~ 8 C \cdot \inparen{\frac{d^2}{D^{d+1}}}.\label{eq:var_univ_bd}
	\end{align}

\begin{align}
	\bigg| \mathbb{E}_{{\bm w}}\bigg[\frac{1}{\|{\bm w}\|_2^d}\bigg] - \frac{1}{D^{d/2}} \bigg| &~\le~ C \cdot \inparen{\frac{d^2}{D^{\frac{d}{2}+1}}}, \label{eq:mean_univ_bd}\\
	\mathsf{Var}_{{\bm w}}\bigg[ \frac{1}{\| {\bm w} \|_2^d}\bigg] &~\le~ 8 C \cdot \inparen{\frac{d^2}{D^{d+1}}}.\label{eq:var_univ_bd}
	\end{align}

It is well-known that the distribution of $\norm{2}{{\bm w}}$ follows a $\chi$-distribution with parameter $D$, and whose probability density function is given by
\begin{equation*}
	f_D(x) = \frac{x^{D-1} \cdot e^{- \frac{x^2}{2}}}{2^{\frac{D}{2} - 1} \cdot \Gamma(\frac{D}{2})},
\end{equation*}
for every $x \geq 0$ (and where $\Gamma(\cdot)$ denotes the Gamma function). Thus, we have that
\begin{align*}
	\mathbb{E}_{{\bm w}}\bigg[\frac{1}{\|{\bm w}\|^d}\bigg] &= \int_{0}^{\infty} \frac{1}{x^d} \cdot f_D(x) dx\\ 
	&=  \int_{0}^{\infty} \frac{x^{D-d-1} \cdot e^{- \frac{x^2}{2}}}{2^{\frac{D}{2} - 1} \cdot \Gamma(\frac{D}{2})} dx\\ 
	&= \frac{2^{\frac{D-d-1}{2}} \cdot \Gamma\inparen{\frac{D-d}{2}}}{2^{\frac{D}{2} - 1} \cdot \Gamma(\frac{D}{2})}\\ 
	&= \frac{1}{D^{d/2}} \cdot \inparen{1 \pm O\inparen{\frac{d^2}{D}}},
\end{align*}
where the last equality follows from the following Stirling's approximation of the Gamma function, which holds for every real number $z > 0$:
\[ \Gamma(z+1) = \sqrt{ 2 \pi z } \cdot \inparen{\frac{z}{e}}^z \cdot \inparen{1 \pm O\inparen{\frac{1}{z}}}. \]
This completes the proof of \Cref{eq:mean_univ_bd}, for the explicit constant $C$ that can be derived from the Stirling's approximation. Now, \Cref{eq:var_univ_bd} immediately follows as:
\begin{align*}
	\mathsf{Var}_{{\bm w}}\insquare{\frac{1}{\| {\bm w} \|^d}} &~=~ \mathbb{E}_{{\bm w}} \insquare{\frac{1}{\|{\bm w}\|^{2d}}} -  \mathbb{E}_{{\bm w}}\insquare{\frac{1}{\|{\bm w}\|^d}}^2\\ 
	&~=~ \inparen{\frac{1}{D^d} \pm C \cdot \inparen{\frac{(2d)^2}{D^{d+1}}}} - \inparen{\frac{1}{D^{d/2}} \pm C \cdot \inparen{\frac{d^2}{D^{d/2+1}}}}^2\\ 
	&~\le~ 8C \cdot \inparen{\frac{d^2}{D^{d+1}}},
\end{align*}
where, we use that $D$ is sufficiently large that $C^2 \inparen{\frac{d^4}{D^{d+2}}} < 2C \cdot \inparen{\frac{d^2}{D^{d+1}}}$, i.e. $D > Cd^2$.

\begin{equation*}
