	&~=~ \mathbb{E}\bigg[\prod_{i=1}^{\ell} \frac{1}{\norm{2}{{\bm w}_i}^{d_i}} \bigg] \cdot \mathbb{E}\bigg[ \prod_{i=\ell+1}^{2\ell} \frac{1}{\norm{2}{{\bm w}_i}^{d_i}}\bigg] ~\pm~ \sqrt{\mathsf{Var}\bigg[\prod_{i=1}^{\ell} \frac{1}{\norm{2}{{\bm w}_i}^{d_i}} \bigg] \cdot \mathsf{Var}\bigg[ \prod_{i=\ell+1}^{2\ell} \frac{1}{\norm{2}{{\bm w}_i}^{d_i}}\bigg]}\;.
\end{align}
Using the inductive assumption w.r.t. $\ell$, we get that,
\begin{align}
