Let $S \subseteq [D]^d$ be the set of all tuples ${\bm c} \in [D]^d$ such that $c_j \neq c_k$ for all $j \neq k \in [d]$. Let $\overline{S}$ denote the complement of $S$ in $[D]^d$. Note that $|\overline{S}| \le d^2 \cdot D^{d-1}$. We have that
\begin{align}
\mathbb{E}\bigg[ \prod_{i=1}^d \langle {\bm u}_i, {\bm v}_i \rangle \bigg] &~=~ \mathbb{E}\bigg[ \prod_{i=1}^d \sum_{k=1}^D u_{i,k} v_{i,k}  \bigg] \nonumber \\ 
&~=~ \mathbb{E} \bigg[ \sum_{{\bm c} \in [D]^d} \prod_{i=1}^d u_{i, c_i} v_{i, c_i} \bigg] \nonumber \\ 
&~=~ \sum_{{\bm c} \in [D]^d} \mathbb{E} \bigg[ \prod_{i=1}^d u_{i, c_i} v_{i, c_i} \bigg] \nonumber \\ 
&~=~ \sum_{{\bm c} \in S} \mathbb{E} \bigg[ \prod_{i=1}^d u_{i, c_i} v_{i, c_i} \bigg] + \sum_{{\bm c} \in \overline{S}} \mathbb{E} \bigg[ \prod_{i=1}^d u_{i, c_i} v_{i, c_i} \bigg] \nonumber\\ 
&~=~ \sum_{{\bm c} \in S} \prod_{i=1}^d \mathbb{E}[ u_{i, c_i} v_{i, c_i}] + \sum_{{\bm c} \in \overline{S}} \mathbb{E} \bigg[ \prod_{i=1}^d u_{i, c_i} v_{i, c_i} \bigg], \label{eq:exp_of_prod}
\end{align}
where the last equality follows from the assumption that the distribution of $(u_{1,j}, \ldots, u_{d,j}, v_{1,j}, \ldots, v_{d,j})$ is independent across $j \in [D]$. On the other hand, we have that
\begin{align}
\prod_{i=1}^d \ \mathbb{E} [ \langle {\bm u}_i, {\bm v}_i \rangle ] &~=~ \prod_{i=1}^d \ \mathbb{E} \bigg[ \sum_{k=1}^D u_{i,k} v_{i,k} \bigg] \nonumber\\
&~=~ \sum_{{\bm c} \in [D]^d} \prod_{i=1}^d \mathbb{E}[ u_{i, c_i} v_{i, c_i}] \nonumber\\
&~=~ \sum_{{\bm c} \in S} \prod_{i=1}^d \mathbb{E}[ u_{i, c_i} v_{i, c_i}] + \sum_{{\bm c} \in \overline{S}} \prod_{i=1}^d \mathbb{E}[ u_{i, c_i} v_{i, c_i}] \label{eq:prod_of_exp}
\end{align}
Combining \Cref{eq:exp_of_prod,eq:prod_of_exp}, we get
\begin{align*}
\bigg| \mathbb{E}\bigg[ \prod_{i=1}^d \langle {\bm u}_i, {\bm v}_i \rangle \bigg] - \prod_{i=1}^d \ \mathbb{E} [ \langle {\bm u}_i, {\bm v}_i \rangle ] \bigg|
&~=~  \bigg|  \sum_{{\bm c} \in \overline{S}} \bigg( \mathbb{E} \bigg[ \prod_{i=1}^d u_{i, c_i} v_{i, c_i}\bigg] - \prod_{i=1}^d \mathbb{E}[ u_{i, c_i} v_{i, c_i}]  \bigg) \bigg|\\ 
&~\le~ |\overline{S}| \cdot \max_{{\bm c} \in \overline{S}} \bigg|  \mathbb{E} \bigg[ \prod_{i=1}^d u_{i, c_i} v_{i, c_i}\bigg] - \prod_{i=1}^d \mathbb{E}[ u_{i, c_i} v_{i, c_i}]  \bigg|\\ 
&~\le~ d^2 \cdot D^{d-1} \cdot \inparen{(2d)^{3d} + 1}\\
&~\le~ d^{O(d)} \cdot D^{d-1},
\end{align*}
where the second last inequality follows from the fact that $|\overline{S}| \le d^2 \cdot D^{d-1}$ and from \Cref{prop:mag_mom_multi_Gauss}.

