\Cref{le:norm_Gauss} now follows immediately by the triangle inequality, for an explicit choice of $D$ that is upper bounded by $\frac{d^{O(d)}}{\delta^2}$.\\

\noindent Note that \Cref{eq:unorm_ineq_norms} is simply a restatement of \Cref{le:swap_exp_prod}. To prove \Cref{eq:norm_ineq_norms}, we define the random variables
\[ W ~:=~ \prod_{i=1}^d \inangle{{\bm u}_i, {\bm v}_i} \qquad \ \mathrm{and} \ \qquad Z ~:=~ \prod_{i=1}^d \frac{1}{\norm{2}{{\bm u}_i} \norm{2}{{\bm v}_i}} ~-~ \frac{1}{D^d}\;. \]
Note that \Cref{eq:norm_ineq_norms} is equivalent to showing bounds on $|\mathbb{E}[W \cdot Z]|$. In order to do so, we show the following four bounds:
\begin{enumerate}
	\item\label{it:W_mean} $\inabs{\mathbb{E}[W]} = D^d + d^{O(d)} \cdot D^{d-1}$.
	\item\label{it:W_var} $\mathsf{Var}[W] = D^{2d} + d^{O(d)} \cdot D^{2d-1}$.
	\item\label{it:Z_mean} $\inabs{\mathbb{E}[Z]} = O\inparen{\frac{d^5}{D^{d+1}}}$. 
	\item\label{it:Z_var} $\mathsf{Var}[Z] = O\inparen{\frac{d^5}{D^{2d+1}}}$. 
\end{enumerate}
We now prove each of these four bounds. We start by proving \Cref{it:W_mean}. By \Cref{le:swap_exp_prod}, we have that
\begin{align*}
	|\mathbb{E}[W]|
	&~\le~ \bigg| \prod_{i=1}^d  \mathbb{E} [ \langle {\bm u}_i, {\bm v}_i \rangle ] \bigg| + d^{O(d)} \cdot D^{d-1}\\
	&~=~ \bigg| \prod_{i=1}^d \sum_{j=1}^D \mathbb{E}[{\bm u}_{i,j} {\bm v}_{i,j}] \bigg| + d^{O(d)} \cdot D^{d-1}\\
	&~\le~ D^d + d^{O(d)} \cdot D^{d-1}
\end{align*}
To prove \Cref{it:W_var}, we can again apply \Cref{le:swap_exp_prod} as follows:
\begin{align*}
	\mathsf{Var}[W] &~\le~ \mathbb{E}[W^2]\\
	&~=~ \mathbb{E} \insquare{\prod_{i=1}^{d} \inangle{{\bm u}_i, {\bm v}_i}^2}\\
	&~\le~ D^{2d} + d^{O(d)} \cdot D^{2d-1}

\end{align*}
Finally, we note that \Cref{it:Z_mean,it:Z_var} follows exactly from \Cref{le:corr_norms_rec_ex}.\\

\noindent To put this together, recall the definition of covariance $\mathsf{Cov}[W,Z] := \mathbb{E}[W \cdot Z] - \mathbb{E}[W] \cdot \mathbb{E}[Z]$, and that by Cauchy-Schwarz inequality, $|\mathsf{Cov}[W,Z]| \le \sqrt{\mathsf{Var}[W] \cdot \mathsf{Var}[Z]}$. Thus,
\begin{align*}
\inabs{\mathbb{E}[W \cdot Z]} &= \inabs{\mathbb{E}[W] \cdot \mathbb{E}[Z] + \mathsf{Cov}(W,Z)}\\ 
&~\le~ \inabs{\mathbb{E}[W] \cdot \mathbb{E}[Z]} + \inabs{\mathsf{Cov}(W,Z)}\\ 
&~\le~ \inabs{\mathbb{E}[W]} \cdot \inabs{\mathbb{E}[Z]} + \sqrt{\mathsf{Var}[W] \cdot \mathsf{Var}[Z]}\\
&~\le~ O\inparen{\frac{d^{2.5}}{\sqrt{D}} + \frac{d^{O(d)}}{D}}
\end{align*}
where the last line combines \Cref{it:W_mean,it:W_var,it:Z_mean,it:Z_var}.

