\begin{align}\label{eq:joint}
	\mathbb{E}\limits_{M} \mathbb{E}\limits_{{\bm a}, {\bm b}} \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{\mathbf{U}_S \mathbf{V}_T \mathbf{U}'_{S'} \mathbf{V}'_{T'}} &= \mathbb{E}\limits_{M} \mathbb{E}\limits_{{\bm a}, {\bm b}} \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{ \prod_{i \in S \cup T \cup S' \cup T'} U_i^{\mathbb{1}(i \in S)} V_i^{\mathbb{1}(i \in T)} {U'}_i^{\mathbb{1}(i \in S')} {V'}_i^{\mathbb{1}(i \in T')}} \nonumber \\ 
	&= \mathbb{E}\limits_{{\bm a}, {\bm b}} \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{ \prod_{i \in S \cup T \cup S' \cup T'} \mathbb{E}\limits_{{\bm m}_i} \insquare{ U_i^{\mathbb{1}(i \in S)} V_i^{\mathbb{1}(i \in T)} {U'}_i^{\mathbb{1}(i \in S')} {V'}_i^{\mathbb{1}(i \in T')}}}.
\end{align}
On the other hand, we have that
\begin{align}\label{eq:first_ind}
	\mathbb{E}\limits_{M} \mathbb{E}\limits_{{\bm a}, {\bm b}} \insquare{\mathbf{U}_S \mathbf{V}_T} &= \mathbb{E}\limits_{{\bm a}, {\bm b}} \mathbb{E}\limits_{M} \insquare{ \prod_{i \in S \cup T} U_i^{\mathbb{1}(i \in S)} V_i^{\mathbb{1}(i \in T)}} = \mathbb{E}\limits_{{\bm a}, {\bm b}} \insquare{ \prod_{i \in S \cup T} \mathbb{E}_{{\bm m}_i} \insquare{U_i^{\mathbb{1}(i \in S)} V_i^{\mathbb{1}(i \in T)}}},
\end{align}
and similarly
\begin{align}\label{eq:sec_ind}
	\mathbb{E}\limits_{M} \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{\mathbf{U}'_{S'} \mathbf{V}'_{T'}} &=  \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{ \prod_{i \in S' \cup T'} \mathbb{E}_{{\bm m}_i} \insquare{U_i^{\mathbb{1}(i \in S')} V_i^{\mathbb{1}(i \in T')}}}.
\end{align}
If there exists $i \in S \cup T \cup S' \cup T'$ that appears in an odd number of $S$, $T$, $S'$ and $T'$, then it can be seen that the expectation in \Cref{eq:joint} is equal to $0$, and that at least one of the expectations in \Cref{eq:first_ind,eq:sec_ind} is equal to $0$. This already handles the case that $S \triangle T \triangle S' \triangle T' \ne \emptyset$.

Henceforth, we assume that each $i \in S \cup T \cup S' \cup T'$ appears in an even number of $S$, $T$, $S'$ and $T'$.
Assume for ease of notation that $S \cup T \cup S' \cup T' \subseteq [4d]$. Define
\begin{align}
g_i({\bm a}, {\bm b}, {\bm a}', {\bm b}') &~:=~ \mathbb{E}_{{\bm m}_i} \insquare{U_i^{\mathbb{1}(i \in S)} V_i^{\mathbb{1}(i \in T)} {U'}_i^{\mathbb{1}(i \in S')} {V'}_i^{\mathbb{1}(i \in T')}} \label{eq:g_function}\\
h_i({\bm a}, {\bm b}) &~:=~ \mathbb{E}_{{\bm m}_i} \insquare{U_i^{\mathbb{1}(i \in S)} V_i^{\mathbb{1}(i \in T)}}.\label{eq:h_function}\\
h_i'({\bm a}', {\bm b}') &~:=~ \mathbb{E}_{{\bm m}_i} \insquare{U_i'^{\mathbb{1}(i \in S')} V_i'^{\mathbb{1}(i \in T')}}.\label{eq:h'_function}
\end{align}
Combining \Cref{eq:joint,eq:first_ind,eq:sec_ind} along with the definitions in \Cref{eq:g_function,eq:h_function,eq:h'_function}, we get
\begin{align*}
	& \bigg| \mathbb{E}\limits_{M} \mathbb{E}\limits_{{\bm a}, {\bm b}} \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{\mathbf{U}_S \mathbf{V}_T \mathbf{U}'_{S'} \mathbf{V}'_{T'}} - \mathbb{E}\limits_{M} \mathbb{E}\limits_{{\bm a}, {\bm b}} \insquare{\mathbf{U}_S \mathbf{V}_T} \cdot \mathbb{E}\limits_{M} \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{\mathbf{U}'_{S'} \mathbf{V}'_{T'}} \bigg|\\ 
	&~=~ \bigg|\mathbb{E}\limits_{{\bm a}, {\bm b}} \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{ \prod_{i = 1}^{4 d} g_i({\bm a}, {\bm b}, {\bm a}', {\bm b}') - \prod_{i = 1}^{4 d} h_i({\bm a}, {\bm b}) \cdot h_i'({\bm a}', {\bm b}')}\bigg|\\ 
	&~=~ \bigg|\mathbb{E}\limits_{{\bm a}, {\bm b}} \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{ \sum_{j=1}^{4d} \insquare{ \prod_{i = 1}^{j-1} h_i({\bm a}, {\bm b}) \cdot h_i'({\bm a}', {\bm b}') \prod_{i = j}^{4d} g_i({\bm a}, {\bm b}, {\bm a}', {\bm b}') - \prod_{i = 1}^{j} h_i({\bm a}, {\bm b}) \cdot h_i'({\bm a}', {\bm b}') \prod_{i = j+1}^{4d} g_i({\bm a}, {\bm b}, {\bm a}', {\bm b}')}}\bigg|\\ 
	&~\le~ \sum_{j=1}^{4d} \ \bigg|\mathbb{E}\limits_{{\bm a}, {\bm b}} \mathbb{E}\limits_{{\bm a}', {\bm b}'} \insquare{ \prod_{i = 1}^{j-1} h_i({\bm a}, {\bm b}) \cdot h_i'({\bm a}', {\bm b}') \prod_{i = j+1}^{4d} g_i({\bm a}, {\bm b}, {\bm a}', {\bm b}') \cdot \insquare{g_j({\bm a}, {\bm b}, {\bm a}', {\bm b}') - h_j({\bm a}, {\bm b}) \cdot h_j'({\bm a}', {\bm b}')}}\bigg|\\ 
	&~\le~ 4 \cdot d \cdot \sqrt{\tau \cdot \kappa},
\end{align*}
where the last inequality follows from the Cauchy-Schwarz inequality with
\begin{align*}
	\tau &~:=~ \max_{j \in [4d]} ~\mathbb{E}\limits_{{\bm a}, {\bm b}} ~\mathbb{E}\limits_{{\bm a}', {\bm b}'} ~\insquare{
		\prod_{i = 1}^{j-1} h_i({\bm a}, {\bm b})^2 \cdot h_i({\bm a}', {\bm b}')^2 \prod_{i = j+1}^{4d} g_i({\bm a}, {\bm b}, {\bm a}', {\bm b}')^2 }\\
	\kappa &~:=~ \max_{j \in [4d]} ~\mathbb{E}\limits_{{\bm a}, {\bm b}} ~\mathbb{E}\limits_{{\bm a}', {\bm b}'} ~\insquare{g_j({\bm a}, {\bm b}, {\bm a}', {\bm b}') - h_j({\bm a}, {\bm b}) \cdot h_j({\bm a}', {\bm b}')}^2
\end{align*}
\Cref{le:square} implies that $\kappa \le O(1/D)$. We now show that $\tau \le 2^{O(d)}$. Note that for any $i \in [D]$, it holds that,
\[
	h_i({\bm a}, {\bm b}) ~=~ \infork{\inangle{\wtilde{{\bm a}}, \wtilde{{\bm b}}} & \ \mathrm{if} \ i \in S \ \mathrm{and} \ i \in T\\ 1 & \ \mathrm{if} \ i \notin S \ \mathrm{and} \ i \notin T \\ 0 & \text{otherwise}}
	\qquad \ \mathrm{and} \ \qquad
