\]
\[
g_i({\bm a}, {\bm b}, {\bm a}', {\bm b}') ~=~ \infork{
	\inangle{\wtilde{{\bm a}}, \wtilde{{\bm b}}}\inangle{\wtilde{{\bm a}}', \wtilde{{\bm b}}'} + \inangle{\wtilde{{\bm a}}, \wtilde{{\bm a}}'}\inangle{\wtilde{{\bm b}}, \wtilde{{\bm b}}'} + \inangle{\wtilde{{\bm a}}, \wtilde{{\bm b}}'}\inangle{\wtilde{{\bm a}}', \wtilde{{\bm b}}} & \ \mathrm{if} \ i \in S \cap T \cap S' \cap T' \\
	\inangle{\wtilde{{\bm a}}, \wtilde{{\bm b}}} & \ \mathrm{if} \ i \in S \cap T \ \mathrm{and} \ i \notin S' \cup T' \\
	\inangle{\wtilde{{\bm a}}, \wtilde{{\bm a}}'} & \ \mathrm{if} \ i \in S \cap S' \ \mathrm{and} \ i \notin T \cup T' \\
	\inangle{\wtilde{{\bm a}}, \wtilde{{\bm b}}'} & \ \mathrm{if} \ i \in S \cap T' \ \mathrm{and} \ i \notin S' \cup T \\
	\inangle{\wtilde{{\bm a}}', \wtilde{{\bm b}}} & \ \mathrm{if} \ i \in S' \cap T \ \mathrm{and} \ i \notin S \cup T' \\
	\inangle{\wtilde{{\bm a}}', \wtilde{{\bm b}}'} & \ \mathrm{if} \ i \in S' \cap T' \ \mathrm{and} \ i \notin S \cup T \\
	\inangle{\wtilde{{\bm b}}, \wtilde{{\bm b}}'} & \ \mathrm{if} \ i \in T \cap T' \ \mathrm{and} \ i \notin S \cup S' \\
	1 & \text{ otherwise}
	}
\]
Thus, if we expand out a single term $\prod_{i = 1}^{j-1} h_i({\bm a}, {\bm b})^2 \cdot h_i({\bm a}', {\bm b}')^2 \prod_{i = j+1}^{4d} g_i({\bm a}, {\bm b}, {\bm a}', {\bm b}')^2$, we get at most $3^{8d}$ terms (since each $g_i$ can multiply the number of terms by at most $3$). Each of these terms is the expectation of the product of inner product of some correlated Gaussian vectors. We thus have from \Cref{le:norm_Gauss} that each such term is at most $1 + \delta$. Thus, we have that $\tau \le 2^{O(d)}$. For an explicit choice of $D$ that is upper bounded by $d^{O(d)}/\delta^2$, we get that $4 d \sqrt{\tau \kappa} \le \delta$, which concludes the proof of the lemma.

