\label{lem:joint_regularity}
	Let $(\mathcal{Z} \times \mathcal{Z}, \mu)$ be a joint probability space. Let $k$, $d \in {\mathbb N}$ and $\tau > 0$ be any given constant parameters. There exists $h \stackrel{\mathrm{def}}{=} h((\mathcal{Z} \times \mathcal{Z}, \mu), k, d, \tau)$ such that the following holds:

	For all degree-$d$ polynomials $P : \mathcal{Z}^n \to {\mathbb R}^k$ and $Q : \mathcal{Z}^n \to {\mathbb R}^k$ such that, $\mathsf{Var}[P_{j}] \le 1$ and $\mathsf{Var}[Q_{j}] \le 1$ for all $j \in [k]$, there exists a subset of indices $H \subseteq [n]$ with $|H| \le h$ such that with probability at least $(1-\tau)$ over the assignment $(\xi_A, \xi_B) \sim \mu^{\otimes h}$, the following holds for any $j \in [k]$ (where we denote $T = [n] \setminus H$),
	\begin{itemize}
		\item the restriction $P_{j}^{\xi_A}(x_T)$ is such that for all $i \in T$, it holds that $\mathrm{Inf}_i(P_{j}^{\xi_A}(x_T)) \le \tau$,
		\item the restriction $Q_{j}^{\xi_B}(y_T)$ is such that for all $i \in T$, it holds that $\mathrm{Inf}_i(Q_{j}^{\xi_B}(y_T)) \le \tau$.
	\end{itemize}
	\noindent In particular, one may take $h = \frac{dk^2}{\tau} \cdot \inparen{\frac{C_4(\alpha)}{\alpha} \log \frac{C_4(\alpha) \cdot k}{\alpha \cdot d \cdot \tau}}^{O(d)}$ which is a constant that depends on $k$, $d$, $\tau$ and $\alpha \stackrel{\mathrm{def}}{=} \alpha(\mu)$, which is the minimum non-zero probability in $\mu$.

\label{lem:our_invariance}
	Let $(\mathcal{Z} \times \mathcal{Z}, \mu)$ be a finite joint probability space, such that $|\mathcal{Z}| = q$ and $\alpha := \alpha(\mu) > 0$ is the minimum probability of any atom in $\mu$. Given parameters $k, d \in {\mathbb N}$ and $\delta > 0$, there exists $\tau = \tau((\mathcal{Z} \times \mathcal{Z}, \mu), k, d, \delta)$ such that the following holds:

	Let $A : \mathcal{Z}^n \to {\mathbb R}^k$ and $B : \mathcal{Z}^n \to {\mathbb R}^k$ be degree-$d$ multilinear polynomials, such that, $\mathsf{Var}(A_j), \mathsf{Var}(B_j) \le 1$ and $\mathrm{Inf}_\ell(A_j), \mathrm{Inf}_\ell(B_j) \le \tau$ for all $\ell \in [n]$ and $j \in [k]$. Then, there exist degree-$d$ multilinear polynomials $\wtilde{A} : {\mathbb R}^{n \cdot (q-1)} \to {\mathbb R}^k$ and $\wtilde{B} : {\mathbb R}^{n \cdot (q-1)} \to {\mathbb R}^k$, such that, for all $i, j \in [k]$, it holds that,
	\begin{equation}\label{eqn:our_invariance}
		\inabs{\inangle{\mathcal{R}_i(\wtilde{A}), \mathcal{R}_j(\wtilde{B})}_{\mathcal{G}_\rho^{\otimes n (q-1)}} ~-~ \inangle{\mathcal{R}_i(A), \mathcal{R}_j(B)}_{\mu^{\otimes n}}} \le \delta\;,
	\end{equation}
	where $\rho = \rho(\mathcal{Z}, \mathcal{Z}; \mu)$ is the maximal correlation of $\mu$. In particular, one may take $\tau =  O\inparen{\frac{\delta^{1.5} \cdot \alpha^{d/2}}{2^{O(d)} \cdot 2^{O(k)}}}$.

	Additionally, the theorem also works in reverse, namely, given degree-$d$ multilinear polynomials $\wtilde{A} : {\mathbb R}^{n} \to {\mathbb R}^k$ and $\wtilde{B} : {\mathbb R}^{n} \to {\mathbb R}^k$, such that $\mathsf{Var}(\wtilde{A}_j), \mathsf{Var}(\wtilde{B}_j) \le 1$ and  $\mathrm{Inf}_\ell(\wtilde{A}_j), \mathrm{Inf}_\ell(\wtilde{B}_j) \le \tau$ for all $\ell \in [n]$ and $j \in [k]$, there exist $A : \mathcal{Z}^n \to {\mathbb R}^k$ and $B : \mathcal{Z}^n \to {\mathbb R}^k$, such that \Cref{eqn:our_invariance} holds.

\begin{equation}\label{eqn:our_invariance}
		\inabs{\inangle{\mathcal{R}_i(\wtilde{A}), \mathcal{R}_j(\wtilde{B})}_{\mathcal{G}_\rho^{\otimes n (q-1)}} ~-~ \inangle{\mathcal{R}_i(A), \mathcal{R}_j(B)}_{\mu^{\otimes n}}} \le \delta\;,
	\end{equation}

 \label{lem:invariance}
	Let $(\Omega^n, \mu^{\otimes n})$ be a finite probability space, such that $\alpha > 0$ is the minimum probability of any atom in $\mu$. Let $\mathcal{F} = (\mathcal{F}_1, \ldots, \mathcal{F}_n)$ be an independent sequence of orthonormal ensembles such that $\mathcal{F}_\ell$  is a basis for functions $\Omega \to {\mathbb R}$, for any $\ell \in [n]$. Let $P$ be a $K$-dimensional multilinear polynomial such that for every $j \in [K]$, it holds that $\mathsf{Var}(P_j) \le 1$, $\deg(P_j) \le d$ and $\mathrm{Inf}_i (P_j) \le \tau$ for every $i \in [n]$. Finally, let $\Psi: {\mathbb R}^K \to {\mathbb R}$ be Lipschitz continuous with Lipschitz constant $L$. Then,
	\[ \inabs{\mathbb{E}_{\mathcal{F}} \Psi(P(\mathcal{F})) - \mathbb{E}_{\mathcal{G}} \Psi(P(\mathcal{G}))} ~\le~ D_K \cdot L \cdot \inparen{d (8/\sqrt{\alpha})^d \sqrt{\tau}}^{1/3}\;,\]
	where $\mathcal{G}$ is an independent sequence of Gaussian ensembles with same covariance structure as $\mathcal{F}$ and $D_K = 2^{O(K)}$.\footnote{Note that the lemma stated in \cite{isaksson2012maximally} does not state the explicit bound of $D_K = 2^{O(K)}$. However, it is possible to infer this bound from their proof.}
